"""Credential providers consumed by the HTTP transport."""

from __future__ import annotations

import time
from collections.abc import Callable
from typing import Protocol

from .config import OAuthCredential

OAUTH_EXPIRY_MARGIN = 60.0


class CredentialProvider(Protocol):
    def authorization_header(self) -> str: ...

    def refresh(self) -> bool: ...


class CredentialRefreshError(Exception):
    """Raised when an expiring credential cannot be refreshed safely."""


class ApiKeyProvider:
    def __init__(self, api_key: str, api_secret: str):
        self._header = f"token {api_key}:{api_secret}"

    def authorization_header(self) -> str:
        return self._header

    def refresh(self) -> bool:
        return False


class OAuthProvider:
    """Own OAuth token rotation, refresh timing, and persistence."""

    def __init__(
        self,
        site: str,
        credential: OAuthCredential,
        refresh_service: Callable[[str, str, str], OAuthCredential],
        persist: Callable[[OAuthCredential], None],
        *,
        clock: Callable[[], float] = time.time,
    ):
        self._site = site
        self._credential = credential
        self._refresh_service = refresh_service
        self._persist = persist
        self._clock = clock

    def authorization_header(self) -> str:
        if (
            self._credential.refresh_token
            and self._credential.expires_at
            and self._credential.expires_at - OAUTH_EXPIRY_MARGIN <= self._clock()
        ):
            if not self._refresh(raise_on_failure=True):
                raise CredentialRefreshError("Could not refresh the OAuth session.")
        return f"Bearer {self._credential.access_token}"

    def refresh(self) -> bool:
        return self._refresh(raise_on_failure=False)

    def _refresh(self, *, raise_on_failure: bool) -> bool:
        if not self._credential.refresh_token:
            return False
        try:
            credential = self._refresh_service(
                self._site,
                self._credential.client_id,
                self._credential.refresh_token,
            )
        except Exception as e:
            if raise_on_failure:
                raise CredentialRefreshError(
                    "Could not refresh the OAuth session. Log in again."
                ) from e
            return False
        if not credential.refresh_token:
            credential = OAuthCredential(
                credential.access_token,
                self._credential.refresh_token,
                credential.expires_at,
                credential.client_id,
            )
        self._credential = credential
        try:
            self._persist(credential)
        except Exception:
            # The fresh token is still usable for this process. A broken
            # keyring must not turn a successful refresh into a failed request.
            pass
        return True

import pytest

from frappectl.site import InsecureCredentialTransport, SiteURL, endpoint_path


def test_site_url_normalizes_input():
    assert str(SiteURL.parse("  example.com/// ")) == "https://example.com"


@pytest.mark.parametrize("host", ["localhost", "dev.localhost", "127.0.0.1", "[::1]"])
def test_site_url_allows_local_plain_http(host):
    SiteURL.parse(f"http://{host}").require_secure_credentials()


def test_site_url_rejects_remote_plain_http():
    with pytest.raises(InsecureCredentialTransport):
        SiteURL.parse("http://example.com").require_secure_credentials()


def test_endpoint_path_quotes_every_dynamic_segment():
    assert (
        endpoint_path("api", "v2", "document", "Sales Invoice", "SINV/1")
        == "/api/v2/document/Sales%20Invoice/SINV%2F1"
    )

import pytest


class FakeKeyring:
    """In-memory stand-in for the OS keyring."""

    def __init__(self):
        self.store: dict[tuple[str, str], str] = {}

    def set_password(self, service, user, password):
        self.store[(service, user)] = password

    def get_password(self, service, user):
        return self.store.get((service, user))

    def delete_password(self, service, user):
        self.store.pop((service, user), None)


@pytest.fixture
def fake_config(tmp_path, monkeypatch):
    """Isolated config dir + in-memory keyring."""
    from frappectl import config

    monkeypatch.setenv("XDG_CONFIG_HOME", str(tmp_path))
    for var in (
        "FRAPPE_SITE",
        "FRAPPE_API_KEY",
        "FRAPPE_API_SECRET",
        "FRAPPE_READ_ONLY",
    ):
        monkeypatch.delenv(var, raising=False)
    kr = FakeKeyring()
    monkeypatch.setattr(config, "_keyring", lambda: kr)
    return config

