import pytest

from frappectl import helpers
from frappectl.errors import UsageError


@pytest.mark.parametrize(
    "token,expected",
    [
        ("status=Paid", ["status", "=", "Paid"]),
        ("grand_total>1000", ["grand_total", ">", 1000]),
        ("amount>=10.5", ["amount", ">=", 10.5]),
        ("qty<=3", ["qty", "<=", 3]),
        ("name!=foo", ["name", "!=", "foo"]),
        ("subject like %report%", ["subject", "like", "%report%"]),
        ("subject not like %x%", ["subject", "not like", "%x%"]),
        ('label="quoted value"', ["label", "=", "quoted value"]),
        ("flag=true", ["flag", "=", True]),
        ("blank=null", ["blank", "=", None]),
    ],
)
def test_parse_filter(token, expected):
    assert helpers.parse_filter(token) == expected


def test_parse_filter_bad():
    with pytest.raises(UsageError):
        helpers.parse_filter("justaword")


def test_parse_set():
    assert helpers.parse_set(["a=1", "b=x", "c=true"]) == {"a": 1, "b": "x", "c": True}


@pytest.mark.parametrize(
    "token,expected",
    [
        # Leading zeros must survive: pincodes, phone numbers, item codes.
        ("pincode=01234", ["pincode", "=", "01234"]),
        ("phone=0123456789", ["phone", "=", "0123456789"]),
        ("code=007", ["code", "=", "007"]),
        ("neg=-007", ["neg", "=", "-007"]),
        ("n=0", ["n", "=", 0]),
        ("f=0.5", ["f", "=", 0.5]),
        ("n=10", ["n", "=", 10]),
    ],
)
def test_parse_filter_preserves_leading_zeros(token, expected):
    assert helpers.parse_filter(token) == expected


def test_parse_set_bad():
    with pytest.raises(UsageError):
        helpers.parse_set(["nope"])


def test_parse_method_params_scalars():
    assert helpers.parse_method_params(["limit=100", "unread=true", "name=x"]) == {
        "limit": 100,
        "unread": True,
        "name": "x",
    }


def test_parse_method_params_json_values():
    # ``key:=value`` parses the value as raw JSON: objects and arrays pass
    # through structurally rather than being flattened to a string.
    assert helpers.parse_method_params(
        [
            'filter:={"inMailbox":"a"}',
            'emails:=["a@example.com","b@example.com"]',
            "count:=3",
            "flag:=false",
            "nothing:=null",
        ]
    ) == {
        "filter": {"inMailbox": "a"},
        "emails": ["a@example.com", "b@example.com"],
        "count": 3,
        "flag": False,
        "nothing": None,
    }


def test_parse_method_params_scalar_with_colon_in_value():
    # A ``:`` inside the value (not immediately before ``=``) stays a scalar.
    assert helpers.parse_method_params(["ts=2026-07-17T10:00:00"]) == {
        "ts": "2026-07-17T10:00:00"
    }


def test_parse_method_params_bad_json():
    with pytest.raises(UsageError):
        helpers.parse_method_params(["filter:={not json}"])


def test_parse_method_params_missing_equals():
    with pytest.raises(UsageError):
        helpers.parse_method_params(["nope"])


def test_parse_fields():
    assert helpers.parse_fields("a,b, c") == ["a", "b", "c"]
    assert helpers.parse_fields("*") == ["*"]
    assert helpers.parse_fields(None) is None


def test_default_fields():
    meta = {
